    section6Body: 'За жените със СПКЯ редовната физическа активност може да е особено полезна: тя подкрепя чувствителността към инсулин, механизъм, често засегнат в този контекст, и може да допринесе за по-добър метаболитен и хормонален баланс в дългосрочен план.',
