    section4Body1: 'Hakuna sheria ya jumla: kinachojalisha zaidi ni uthabiti kuliko utendaji. Kuweka vipindi vifupi vya mwendo katika siku yako (kutembea, kupanda ngazi, kunyoosha mwili) kunahesabika sawa na mazoezi yaliyopangwa.',
