    section1Body1: 'Nakakaimpluwensya ang regular na pisikal na aktibidad sa maraming sistema ng katawan, kabilang ang mga kasangkot sa regulasyon ng hormone at paggana ng siklo ng regla. Partikular itong kumikilos sa pagiging sensitibo sa insulin, pangangasiwa ng stress, at kalidad ng tulog — tatlong salik na nakikipag-ugnayan sa hormonal na balanse.',
    section1Body2: 'Hindi ginagarantiyahan ng regular na pagkilos ang isang “perpektong” siklo, ngunit isa ito sa mga gawing sumusuporta sa mabuting pangkalahatang kalusugan, na may mga epektong maaaring makita sa siklo ng ilang babae.',
