    section4Body1: 'Walang pangkalahatang tuntunin: ang pinakamahalaga ay ang pagiging regular kaysa sa performance. Kasimbigat ng nakaplanong ehersisyo ang pagsisingit ng maiikling kilos sa iyong araw (paglalakad, pag-akyat ng hagdan, pag-unat).',
    section4Body2: 'Nakadepende ang tamang tindi sa antas ng iyong fitness, kalusugan, enerhiya mo sa sandaling iyon, at mga personal mong layunin: ang gumagana para sa isa ay hindi kinakailangang gumana para sa iba.',
    highlightTitle: 'Unahin ang pagiging regular',
