    section6Body: 'Para sa mga babaeng may PCOS, maaaring maging lubhang kapaki-pakinabang ang regular na pisikal na aktibidad: sinusuportahan nito ang pagiging sensitibo sa insulin, mekanismong madalas na apektado sa kontekstong ito, at maaaring mag-ambag sa mas mahusay na metabolic at hormonal na balanse sa mahabang panahon.',
