    section1Body1: 'தொடர்ந்த உடல் செயல்பாடு, ஹார்மோன் ஒழுங்குமுறையிலும் மாதவிடாய்ச் சுழற்சி செயல்படும் விதத்திலும் ஈடுபட்டுள்ளவை உட்பட, உடலின் பல அமைப்புகளைப் பாதிக்கிறது. இது குறிப்பாக இன்சுலின் உணர்திறன், மன அழுத்த மேலாண்மை மற்றும் உறக்கத் தரம் ஆகியவற்றில் செயல்படுகிறது — இந்த மூன்று காரணிகளும் ஹார்மோன் சமநிலையுடன் இடைவினை புரிகின்றன.',
