    neutral2Text: 'ఇవి కఠినమైన శారీరక నియమాలు కావు: ప్రతి మహిళ తన చక్రాన్ని భిన్నంగా అనుభవిస్తుంది, ఈ ఉదాహరణలు సూచనా బిందువులు, తప్పనిసరి బాధ్యతలు కావు.',
    section6Body: 'PCOS ఉన్న మహిళలకు, క్రమమైన శారీరక కార్యకలాపం ప్రత్యేకంగా సహాయపడవచ్చు: ఇది ఈ సందర్భంలో తరచుగా ప్రభావితమయ్యే యంత్రాంగమైన ఇన్సులిన్ సున్నితత్వానికి తోడ్పడుతుంది, దీర్ఘకాలంలో మెరుగైన జీవక్రియ, హార్మోన్ సమతుల్యతకు దోహదపడవచ్చు.',
