    intro: 'ເປັນຫຍັງການອອກກຳລັງກາຍຢ່າງສະໝ່ຳສະເໝີອາດສະໜັບສະໜູນຄວາມສົມດຸນຂອງຮອບເດືອນ ການເຄື່ອນໄຫວປະເພດໃດທີ່ຄວນເລືອກ ແລະ ວິທີປັບຈັງຫວະຂອງທ່ານໂດຍບໍ່ມີຄວາມກົດດັນ ຫຼື ຄວາມຮູ້ສຶກຜິດ.',
    introSecondary: 'ບໍ່ແມ່ນການເຮັດໃຫ້ຫຼາຍຂຶ້ນ ແຕ່ແມ່ນການເຄື່ອນໄຫວແບບທີ່ເໝາະກັບທ່ານ ແລະ ທ່ານຮັກສາໄດ້ໃນໄລຍະຍາວ.',
    contentsTitle: 'ໃນບົດຄວາມນີ້',
